#include <vector>
#include <string>
#include <algorithm>

using namespace std;

class Solution {
public:
    vector<string> removeSubfolders(vector<string>& folder) {
        sort(folder.begin(), folder.end());
        vector<string> res;
        string prev = "";
        for (string& f : folder) {
            if (prev.empty() || f.compare(0, prev.length(), prev) != 0 || f[prev.length()] != '/')
                res.push_back(prev = f);
        }
        return res;
    }
};
